 5	    private static void siftDown(int[] values, int heapSize, int startIndex) {
 6	        int currentIndex = startIndex;
 7	
 8	        while (hasLeftChild(currentIndex, heapSize)) {
 9	            int largerChildIndex = largerChildIndex(values, heapSize, currentIndex);
10	
11	            if (values[currentIndex] >= values[largerChildIndex]) {
12	                return;
13	            }
14	
15	            swap(values, currentIndex, largerChildIndex);
16	            currentIndex = largerChildIndex;
17	        }
18	    }
