24	    private static int largerChildIndex(int[] values, int heapSize, int parentIndex) {
25	        int leftChildIndex = leftChildIndex(parentIndex);
26	        int rightChildIndex = rightChildIndex(parentIndex);
27	
28	        if (rightChildIndex < heapSize && values[rightChildIndex] > values[leftChildIndex]) {
29	            return rightChildIndex;
30	        }
31	
32	        return leftChildIndex;
33	    }
